package com.esn.smp.gameplay;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;
public final class ServerMenus implements Listener,CommandExecutor{
 private final JavaPlugin p;private static final String TITLE=ChatColor.DARK_PURPLE+"ESN Server Hub";private static final String SUB=ChatColor.DARK_AQUA+"ESN • ";
 public ServerMenus(JavaPlugin p){this.p=p;}
 private ItemStack item(Material m,String n,String...l){ItemStack i=new ItemStack(m);ItemMeta x=i.getItemMeta();x.setDisplayName(n);x.setLore(Arrays.asList(l));i.setItemMeta(x);return i;}
 public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player x)){s.sendMessage("Players only.");return true;}open(x);return true;} public void openSystem(Player x,String system){Inventory v=Bukkit.createInventory(null,54,SUB+system);String[][] opts=switch(system){case "Bosses"->new String[][]{{"World Boss","boss world"},{"Boss Codex","bosscodex"},{"Boss Drops","bossdrops"},{"Boss Summon","bosssummon"},{"Boss Rush","bossrush"}};case "Jobs"->new String[][]{{"Jobs","jobs"},{"Skills","skills"},{"Prestige","prestige"},{"Stats","stats"},{"Collections","collections"}};case "Forge"->new String[][]{{"Forge","forge"},{"Blacksmith","blacksmith"},{"Salvage","salvage"},{"Reforge","reforge"},{"Gear Upgrade","gearupgrade"},{"Rune Forge","runeforge"}};case "Progression"->new String[][]{{"Progression","progression"},{"Season Pass","seasonpass"},{"Achievements","achievements"},{"Challenges","challenges"},{"Rewards","rewards"},{"Milestones","milestones"}};case "Adventure"->new String[][]{{"Adventure","adventure"},{"Class","class"},{"Rift","rift"},{"Hunt","hunt"},{"Bounty Board","bountyboard"},{"Trophies","trophies"}};default->new String[][]{{system,system.toLowerCase()}};};int slot=10;for(String[]o:opts){v.setItem(slot++,item(Material.NETHER_STAR,ChatColor.GOLD+o[0],ChatColor.GRAY+"/"+o[1]));if(slot==17)slot=19;}v.setItem(49,item(Material.ARROW,ChatColor.YELLOW+"Back",ChatColor.GRAY+"Return to server hub"));x.openInventory(v);}
 public void open(Player x){Inventory v=Bukkit.createInventory(null,54,TITLE);v.setItem(10,item(Material.CHEST,ChatColor.GOLD+"Crates",ChatColor.GRAY+"/crates"));v.setItem(11,item(Material.NETHER_STAR,ChatColor.RED+"Bosses",ChatColor.GRAY+"/boss"));v.setItem(12,item(Material.ENDER_EYE,ChatColor.LIGHT_PURPLE+"Adventure",ChatColor.GRAY+"/adventure"));v.setItem(13,item(Material.DIAMOND_SWORD,ChatColor.AQUA+"RPG Profile",ChatColor.GRAY+"/rpgprofile"));v.setItem(14,item(Material.WRITABLE_BOOK,ChatColor.YELLOW+"Quests",ChatColor.GRAY+"/quests"));v.setItem(15,item(Material.CLOCK,ChatColor.GREEN+"Events",ChatColor.GRAY+"/event"));v.setItem(16,item(Material.BEACON,ChatColor.AQUA+"Warps",ChatColor.GRAY+"/warps"));v.setItem(19,item(Material.ANVIL,ChatColor.GRAY+"Blacksmith",ChatColor.GRAY+"/blacksmith"));v.setItem(20,item(Material.SMITHING_TABLE,ChatColor.GOLD+"Forge",ChatColor.GRAY+"/forge"));v.setItem(21,item(Material.ENCHANTING_TABLE,ChatColor.LIGHT_PURPLE+"Runes",ChatColor.GRAY+"/runes"));v.setItem(22,item(Material.DIAMOND,ChatColor.AQUA+"Relics",ChatColor.GRAY+"/relics"));v.setItem(23,item(Material.OAK_SIGN,ChatColor.YELLOW+"Jobs",ChatColor.GRAY+"/jobs"));v.setItem(24,item(Material.EXPERIENCE_BOTTLE,ChatColor.GREEN+"Skills",ChatColor.GRAY+"/skills"));v.setItem(25,item(Material.PLAYER_HEAD,ChatColor.WHITE+"Profile",ChatColor.GRAY+"/profile"));v.setItem(28,item(Material.SHIELD,ChatColor.BLUE+"Claims",ChatColor.GRAY+"/claim info"));v.setItem(29,item(Material.ENDER_CHEST,ChatColor.DARK_AQUA+"Auction House",ChatColor.GRAY+"/ah"));v.setItem(30,item(Material.GOLD_INGOT,ChatColor.GOLD+"Shop",ChatColor.GRAY+"/shop"));v.setItem(31,item(Material.BOOK,ChatColor.YELLOW+"Guide",ChatColor.GRAY+"/guide"));v.setItem(32,item(Material.TOTEM_OF_UNDYING,ChatColor.GOLD+"Season Pass",ChatColor.GRAY+"/seasonpass"));v.setItem(33,item(Material.DRAGON_HEAD,ChatColor.DARK_PURPLE+"Boss Codex",ChatColor.GRAY+"/bosscodex"));v.setItem(34,item(Material.COMPASS,ChatColor.AQUA+"Progression",ChatColor.GRAY+"/progression"));v.setItem(40,item(Material.BARRIER,ChatColor.RED+"Close"));x.openInventory(v);}
 @EventHandler public void click(InventoryClickEvent e){if(!e.getView().getTitle().equals(TITLE))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player x)||e.getCurrentItem()==null||!e.getCurrentItem().hasItemMeta())return;String n=ChatColor.stripColor(e.getCurrentItem().getItemMeta().getDisplayName());if(e.getView().getTitle().startsWith(SUB)){if(n.equals("Back")){open(x);return;}ItemMeta im=e.getCurrentItem().getItemMeta();if(im.hasLore()&&!im.getLore().isEmpty()){String line=ChatColor.stripColor(im.getLore().get(0));if(line.startsWith("/")){x.closeInventory();Bukkit.dispatchCommand(x,line.substring(1));}}return;}Map<String,String>m=Map.ofEntries(Map.entry("Crates","crates"),Map.entry("Bosses","boss"),Map.entry("Adventure","adventure"),Map.entry("RPG Profile","rpgprofile"),Map.entry("Quests","quests"),Map.entry("Events","event"),Map.entry("Warps","warps"),Map.entry("Blacksmith","blacksmith"),Map.entry("Forge","forge"),Map.entry("Runes","runes"),Map.entry("Relics","relics"),Map.entry("Jobs","jobs"),Map.entry("Skills","skills"),Map.entry("Profile","profile"),Map.entry("Claims","claim info"),Map.entry("Auction House","ah"),Map.entry("Shop","shop"),Map.entry("Guide","guide"),Map.entry("Season Pass","seasonpass"),Map.entry("Boss Codex","bosscodex"),Map.entry("Progression","progression"));if(n.equals("Close")){x.closeInventory();return;}String cmd=m.get(n);if(cmd!=null){if(Set.of("Bosses","Adventure","Jobs","Blacksmith","Forge","Runes","Relics","Skills","Season Pass","Boss Codex","Progression").contains(n)){String group=switch(n){case "Bosses","Boss Codex"->"Bosses";case "Adventure"->"Adventure";case "Jobs","Skills"->"Jobs";case "Blacksmith","Forge","Runes","Relics"->"Forge";default->"Progression";};openSystem(x,group);}else{x.closeInventory();Bukkit.dispatchCommand(x,cmd);}}}
}